const ACOPLA_LP_STYLES = String.raw`@import url('https://fonts.googleapis.com/css2?family=Cabinet+Grotesk:wght@400;500;600;700;800;900&family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;1,9..40,400&family=DM+Mono:wght@400;500&display=swap');
:host{--green:#00602a;--green-d:#004d22;--green-xl:#003318;--lime:#bcdb05;--lime-d:#a3bf04;--lime-l:rgba(188,219,5,.12);--white:#ffffff;--off:#f5f4ef;--off2:#eeece3;--dark:#080f06;--dark2:#0d1a09;--dark3:#111e0d;--text:#0f1a0b;--muted:#6b6b5c;--border:#e0ddd2;--amber:#d97706;--syne:'Cabinet Grotesk',sans-serif;--body:'DM Sans',sans-serif;--mono:'DM Mono',monospace;--r:12px;--r2:20px;display:block;width:100%;font-family:var(--body);background:var(--dark);color:var(--text);line-height:1.65}
.acopla-lp-root{font-family:var(--body);background:var(--dark);color:var(--text);overflow-x:hidden;line-height:1.65}
/* Extracted from index.html. Keep this file as the visual source for the static LP. */
:root {
  --green:#00602a; --green-d:#004d22; --green-xl:#003318;
  --lime:#bcdb05; --lime-d:#a3bf04; --lime-l:rgba(188,219,5,.12);
  --white:#ffffff; --off:#f5f4ef; --off2:#eeece3;
  --dark:#080f06; --dark2:#0d1a09; --dark3:#111e0d;
  --text:#0f1a0b; --muted:#6b6b5c; --border:#e0ddd2;
  --amber:#d97706;
  --syne:'Cabinet Grotesk',sans-serif; --body:'DM Sans',sans-serif; --mono:'DM Mono',monospace;
  --r:12px; --r2:20px;
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;scrollbar-width:none;-ms-overflow-style:none;overflow-x:hidden;background:var(--dark)}
html::-webkit-scrollbar{display:none}
body{font-family:var(--body);background:var(--dark);color:var(--text);overflow-x:hidden;line-height:1.65}
a{text-decoration:none;color:inherit}
img,svg{display:block;max-width:100%}

/* SCROLL PROGRESS */
#sp{position:fixed;top:0;left:0;height:2px;background:var(--lime);z-index:400;width:0;transition:width .1s linear}

/* NAV */
#nav{position:fixed;top:0;left:0;right:0;z-index:300;height:82px;display:flex;align-items:center;justify-content:space-between;padding:0 clamp(22px,5vw,72px);transition:all .35s}
#nav::before{content:'';position:absolute;inset:12px clamp(14px,4vw,52px);border:1px solid rgba(255,255,255,.1);border-radius:999px;background:rgba(8,15,6,.72);backdrop-filter:blur(18px);box-shadow:0 18px 54px rgba(0,0,0,.2);transition:all .35s}
#nav>*{position:relative;z-index:1}
#nav.scrolled{background:transparent;backdrop-filter:none;box-shadow:none}
#nav.scrolled::before{background:rgba(255,255,255,.94);border-color:var(--border);box-shadow:0 14px 42px rgba(15,26,11,.08)}
.nav-logo{display:flex;align-items:center;gap:18px;padding-left:12px;transition:opacity .3s,transform .25s}
.nav-logo:hover{opacity:.9;transform:translateY(-1px)}
.nav-logo img{height:50px;width:auto;object-fit:contain;filter:brightness(0) invert(1);transition:filter .3s,opacity .3s}
.nav-logo img.logo-acp{height:39px}
#nav.scrolled .nav-logo img{filter:none}
.nav-logo-divider{width:1px;height:42px;background:rgba(255,255,255,.2)}
#nav.scrolled .nav-logo-divider{background:var(--border)}
.nav-links{display:flex;align-items:center;gap:6px;list-style:none;padding:6px;border:1px solid rgba(255,255,255,.1);border-radius:999px;background:rgba(255,255,255,.045);backdrop-filter:blur(14px)}
#nav.scrolled .nav-links{background:rgba(245,244,239,.86);border-color:var(--border)}
.nav-links a{display:inline-flex;align-items:center;justify-content:center;min-height:34px;padding:0 12px;border-radius:999px;font-size:.72rem;font-weight:700;color:rgba(255,255,255,.68);transition:color .2s,background .2s,box-shadow .2s,transform .2s;letter-spacing:.02em}
#nav.scrolled .nav-links a{color:var(--muted)}
.nav-links a:hover{color:var(--dark);background:var(--lime);box-shadow:0 10px 24px rgba(188,219,5,.22);transform:translateY(-1px)}
#nav.scrolled .nav-links a:hover{color:var(--dark)}
.nav-contact{display:flex;align-items:center;gap:8px;font-size:.72rem;font-weight:700;color:rgba(255,255,255,.78);white-space:nowrap;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.08);border-radius:999px;padding:0 10px}
#nav.scrolled .nav-contact{color:var(--green)}
.nav-contact span{color:rgba(255,255,255,.28)}
#nav.scrolled .nav-contact span{color:var(--border)}
.nav-contact a{min-height:auto;padding:0 !important;color:inherit !important;background:transparent !important;box-shadow:none !important}
.nav-contact a:hover{color:var(--lime) !important;transform:none}
#nav.scrolled .nav-contact a:hover{color:var(--green-d) !important}
.nav-cta{background:var(--lime) !important;color:var(--dark) !important;padding:0 20px !important;min-height:38px;border-radius:100px;font-weight:800 !important;font-size:.75rem !important;transition:all .2s !important;letter-spacing:.02em !important;box-shadow:0 10px 28px rgba(188,219,5,.25)}
.nav-cta:hover{background:#cde405 !important;transform:translateY(-1px);box-shadow:0 14px 34px rgba(188,219,5,.34) !important}
.nav-mob{display:none;background:var(--lime);color:var(--dark);padding:10px 18px;border-radius:100px;font-size:.78rem;font-weight:800;box-shadow:0 12px 28px rgba(188,219,5,.24)}

/* UTILS */
.w{max-width:1200px;margin:0 auto;padding:0 5%}
.sec{padding:108px 0}
.sec-sm{padding:80px 0}
.eyebrow{display:inline-flex;align-items:center;gap:9px;font-size:.64rem;font-weight:700;text-transform:uppercase;letter-spacing:.16em;color:var(--lime-d);margin-bottom:14px}
.eyebrow::before{content:'';display:inline-block;width:20px;height:1.5px;background:var(--lime-d)}
.h2{font-family:var(--syne);font-size:clamp(2rem,3.4vw,3.1rem);font-weight:800;line-height:1.06;letter-spacing:-.035em}
.lead{font-size:.96rem;color:var(--muted);line-height:1.8;max-width:520px;margin-top:14px}
.brand-pair{display:inline-flex;align-items:center;gap:18px;flex-wrap:wrap;margin-bottom:22px;background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.1);border-radius:14px;padding:14px 18px;box-shadow:0 18px 42px rgba(0,0,0,.16);animation:fadeUp .55s ease forwards .05s;opacity:0}
.brand-pair img{height:48px;width:auto;object-fit:contain;filter:brightness(0) invert(1)}
.brand-pair img.logo-acp{height:38px}
.brand-pair span{width:1px;height:38px;background:rgba(255,255,255,.16)}

/* REVEAL */
[data-r]{opacity:0;transform:translateY(24px);transition:opacity .65s ease,transform .65s ease}
[data-r=l]{transform:translateX(-24px)}
[data-r=r]{transform:translateX(24px)}
[data-r=s]{transform:scale(.96)}
[data-r].on{opacity:1;transform:none}
[data-d="1"]{transition-delay:.1s}[data-d="2"]{transition-delay:.2s}
[data-d="3"]{transition-delay:.3s}[data-d="4"]{transition-delay:.4s}
[data-d="5"]{transition-delay:.5s}[data-d="6"]{transition-delay:.6s}

/* BTNS */
.btn{display:inline-flex;align-items:center;gap:8px;padding:12px 22px;border-radius:100px;font-weight:600;font-size:.82rem;font-family:var(--body);transition:all .25s;cursor:pointer;border:none;white-space:nowrap;letter-spacing:.01em}
.btn-lime{background:var(--lime);color:var(--dark)}
.btn-lime:hover{background:#cde405;transform:translateY(-2px);box-shadow:0 10px 28px rgba(188,219,5,.3)}
.btn-g{background:var(--green);color:var(--white)}
.btn-g:hover{background:var(--green-d);transform:translateY(-2px);box-shadow:0 10px 28px rgba(0,96,42,.22)}
.btn-ow{border:1.5px solid rgba(255,255,255,.2);color:rgba(255,255,255,.7);padding:12px 20px;border-radius:100px;font-size:.8rem;font-weight:500;transition:all .2s;display:inline-flex;align-items:center;gap:8px}
.btn-ow:hover{border-color:rgba(255,255,255,.5);color:#fff}
.btn-ob{border:1.5px solid var(--border);color:var(--muted);padding:13px 24px;border-radius:100px;font-size:.83rem;font-weight:500;transition:all .2s;display:inline-flex;align-items:center;gap:8px;cursor:pointer;background:transparent;font-family:var(--body)}
.btn-ob:hover{border-color:var(--green);color:var(--green)}

/* ===================== HERO ===================== */
#hero{min-height:100svh;background:var(--dark);display:flex;align-items:center;padding:92px 0 34px;position:relative;overflow:hidden}
.hero-grid{position:absolute;inset:0;background-image:linear-gradient(rgba(188,219,5,.04) 1px,transparent 1px),linear-gradient(90deg,rgba(188,219,5,.04) 1px,transparent 1px);background-size:60px 60px}
.hero-glow1{position:absolute;top:-20%;left:-10%;width:60%;height:80%;background:radial-gradient(ellipse,rgba(0,96,42,.18) 0%,transparent 60%);pointer-events:none}
.hero-glow2{position:absolute;bottom:-20%;right:-5%;width:50%;height:70%;background:radial-gradient(ellipse,rgba(188,219,5,.06) 0%,transparent 60%);pointer-events:none}
.hero-wrap{max-width:1200px;margin:0 auto;padding:0 5%;display:grid;grid-template-columns:1.03fr .97fr;gap:42px;align-items:center;position:relative;z-index:1}
.hero-pre{display:inline-flex;align-items:center;gap:7px;background:rgba(188,219,5,.08);border:1px solid rgba(188,219,5,.2);color:var(--lime);font-size:.62rem;font-weight:700;padding:4px 12px;border-radius:100px;letter-spacing:.1em;text-transform:uppercase;margin-bottom:18px;animation:fadeUp .55s ease forwards .1s;opacity:0}
.hero-pre-dot{width:6px;height:6px;border-radius:50%;background:var(--lime);animation:pulse 2s ease infinite}
.hero-h1{font-family:var(--syne);font-size:clamp(2.15rem,4.45vw,3.72rem);font-weight:800;color:var(--white);line-height:1.01;letter-spacing:-.045em;margin-bottom:16px;animation:fadeUp .65s ease forwards .2s;opacity:0}
.hero-h1 .acc{color:var(--lime);display:block}
.hero-h1 .acc2{color:rgba(255,255,255,.55)}
.hero-sub{font-size:.9rem;color:rgba(255,255,255,.45);line-height:1.62;max-width:500px;margin-bottom:10px;animation:fadeUp .65s ease forwards .35s;opacity:0}
.hero-quote-wrap{margin-bottom:22px;animation:fadeUp .65s ease forwards .45s;opacity:0}
.hero-quote{background:rgba(188,219,5,.07);border-left:3px solid var(--lime);border-radius:0 10px 10px 0;padding:11px 16px;font-size:.82rem;color:rgba(255,255,255,.7);line-height:1.45;font-style:italic}
.hero-quote strong{color:var(--lime);font-style:normal}
.hero-acts{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:28px;animation:fadeUp .65s ease forwards .55s;opacity:0}
.hero-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:rgba(255,255,255,.06);border-radius:14px;overflow:hidden;animation:fadeUp .65s ease forwards .7s;opacity:0}
.hero-vis .hero-stats{margin-bottom:14px;width:100%;box-shadow:0 18px 46px rgba(0,0,0,.16)}
.hs{background:rgba(255,255,255,.03);padding:15px 15px}
.hs-val{font-family:var(--syne);font-size:1.48rem;font-weight:800;color:var(--white);line-height:1}
.hs-val em{color:var(--lime);font-style:normal;font-size:1.1rem}
.hs-lab{font-size:.64rem;color:rgba(255,255,255,.3);margin-top:4px;line-height:1.32;letter-spacing:.01em}

/* HERO VISUAL */
.hero-vis{animation:fadeIn .9s ease forwards .8s;opacity:0;display:flex;flex-direction:column;align-items:stretch}
.hv-card{background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);border-radius:18px;padding:22px;margin-bottom:10px}
.hv-card-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}
.hvc-label{font-size:.64rem;font-weight:600;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.1em;font-family:var(--mono)}
.hvc-badge{display:flex;align-items:center;gap:6px;font-size:.62rem;font-weight:700;color:var(--lime);background:rgba(188,219,5,.1);border:1px solid rgba(188,219,5,.2);padding:3px 10px;border-radius:100px}
.hvc-badge-dot{width:5px;height:5px;border-radius:50%;background:var(--lime);animation:pulse 2s ease infinite}
.hv-costs{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px}
.hvc-item{background:rgba(255,255,255,.04);border-radius:10px;padding:10px 12px}
.hvc-item-l{font-size:.64rem;color:rgba(255,255,255,.35);margin-bottom:4px}
.hvc-item-v{font-family:var(--syne);font-size:1rem;font-weight:700;color:rgba(255,255,255,.75)}
.hvc-item-v.red{color:#f87171}
.hvc-item-v.grn{color:#4ade80}
.hv-saving{background:rgba(188,219,5,.08);border:1px solid rgba(188,219,5,.18);border-radius:10px;padding:12px 16px;display:flex;justify-content:space-between;align-items:center}
.hvs-l{font-size:.72rem;color:rgba(255,255,255,.45)}
.hvs-v{font-family:var(--syne);font-size:1.05rem;font-weight:800;color:var(--lime)}
.hv-tags{display:flex;flex-wrap:wrap;gap:7px;margin-top:6px}
.hv-tag{font-size:.62rem;font-weight:600;color:rgba(255,255,255,.35);background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.07);padding:4px 10px;border-radius:100px}

/* ===================== TICKER ===================== */
.ticker{background:var(--green);overflow:hidden;padding:12px 0;white-space:nowrap}
.ti{display:inline-flex;animation:tick 35s linear infinite}
.ti-item{display:inline-flex;align-items:center;font-size:.7rem;font-weight:600;color:rgba(255,255,255,.55);text-transform:uppercase;letter-spacing:.1em;padding:0 22px}
.ti-dot{width:4px;height:4px;border-radius:50%;background:var(--lime);margin-left:22px;flex-shrink:0}

/* ===================== PAIN SECTION ===================== */
#dor{background:var(--off)}
.tem-band{background:linear-gradient(135deg,var(--green-xl) 0%,var(--dark) 54%,#152506 100%);padding:56px 0;border-top:1px solid rgba(188,219,5,.22);border-bottom:1px solid rgba(188,219,5,.22);position:relative;overflow:hidden}
.tem-band::before{content:'';position:absolute;inset:0;background-image:linear-gradient(rgba(188,219,5,.055) 1px,transparent 1px),linear-gradient(90deg,rgba(188,219,5,.045) 1px,transparent 1px);background-size:48px 48px;opacity:.8}
.tem-band::after{content:'TEM';position:absolute;right:5%;top:50%;transform:translateY(-50%);font-family:var(--syne);font-size:clamp(5rem,14vw,11rem);font-weight:900;letter-spacing:-.08em;color:rgba(188,219,5,.055);line-height:1;pointer-events:none}
.tem-inner{position:relative;z-index:1;display:grid;grid-template-columns:1fr auto;gap:36px;align-items:center}
.tem-kicker{display:inline-flex;align-items:center;gap:8px;font-family:var(--mono);font-size:.66rem;font-weight:700;color:var(--lime);text-transform:uppercase;letter-spacing:.16em;margin-bottom:12px}
.tem-kicker::before{content:'';width:26px;height:2px;background:var(--lime)}
.tem-title{font-family:var(--syne);font-size:clamp(2rem,4vw,3.4rem);font-weight:900;color:var(--white);letter-spacing:-.045em;line-height:.98;margin-bottom:14px;text-wrap:balance}
.tem-title span{color:var(--lime)}
.tem-text{font-size:1rem;color:rgba(255,255,255,.62);line-height:1.72;max-width:840px}
.tem-link{display:inline-flex;align-items:center;justify-content:center;background:var(--lime);color:var(--dark);border-radius:999px;padding:15px 28px;font-size:.86rem;font-weight:900;white-space:nowrap;box-shadow:0 16px 38px rgba(188,219,5,.22);transition:transform .22s,box-shadow .22s,background .22s}
.tem-link:hover{background:#cde405;transform:translateY(-2px);box-shadow:0 20px 46px rgba(188,219,5,.32)}
.pain-head{display:flex;flex-direction:column;align-items:center;text-align:center;gap:18px;margin-bottom:58px}
.pain-head [data-r]{display:flex;flex-direction:column;align-items:center}
.pain-head .eyebrow{justify-content:center}
.pain-head .eyebrow::before{display:none}
.pain-head .h2{max-width:910px}
.pain-right-text{font-size:clamp(1.08rem,1.65vw,1.34rem);color:#4f5246;line-height:1.72;max-width:920px;margin:0 auto}
.pain-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}
.pain-card{background:var(--white);border:1px solid var(--border);border-radius:var(--r2);padding:28px;position:relative;overflow:hidden;transition:all .25s;cursor:default;display:grid;grid-template-columns:auto 1fr;grid-template-areas:"num num" "icon title" "text text";column-gap:16px;align-items:center}
.pain-card::before{content:'';position:absolute;bottom:0;left:0;height:3px;width:0;background:linear-gradient(90deg,var(--green),var(--lime-d));transition:width .4s}
.pain-card:hover{box-shadow:0 10px 34px rgba(0,0,0,.07);border-color:transparent;transform:translateY(-2px)}
.pain-card:hover::before{width:100%}
.pc-num{grid-area:num;font-family:var(--mono);font-size:.58rem;color:#bdb9ad;letter-spacing:.1em;margin-bottom:18px}
.pc-icon{grid-area:icon;font-size:2rem;line-height:1;margin-bottom:0}
.pain-card h3{grid-area:title;font-family:var(--syne);font-size:1.1rem;font-weight:800;color:var(--text);margin-bottom:0;line-height:1.18}
.pain-card p{grid-area:text;font-size:.84rem;color:var(--muted);line-height:1.7;margin-top:15px}
.pain-highlight{margin-top:44px;background:var(--dark);border-radius:var(--r2);padding:36px 40px;display:flex;align-items:center;gap:28px}
.ph-icon{font-size:2.2rem;flex-shrink:0}
.ph-text p{font-size:.95rem;color:rgba(255,255,255,.6);line-height:1.75}
.ph-text strong{color:var(--lime)}

/* ===================== QUOTE BANNER ===================== */
#quote-banner{background:var(--green);padding:80px 0}
.qb-inner{text-align:center;max-width:860px;margin:0 auto}
.qb-mark{font-size:5rem;color:rgba(255,255,255,.1);font-family:var(--syne);line-height:1;margin-bottom:-20px}
.qb-text{font-family:var(--syne);font-size:clamp(1.3rem,2.6vw,2.1rem);font-weight:700;color:var(--white);line-height:1.3;letter-spacing:-.02em;margin-bottom:20px}
.qb-text em{color:var(--lime);font-style:normal}
.qb-sub{font-size:.85rem;color:rgba(255,255,255,.5);line-height:1.7;max-width:580px;margin:0 auto}

/* ===================== DIFFERENCIAL ===================== */
#diferencial{background:var(--white)}
.dif-layout{display:grid;grid-template-columns:1fr 1fr;gap:72px;align-items:center}
.dif-vis{position:relative}
.dif-card{background:var(--dark);border-radius:20px;padding:32px;color:white;overflow:hidden;position:relative}
.dif-card::before{content:'';position:absolute;top:-40px;right:-40px;width:180px;height:180px;border-radius:50%;background:radial-gradient(rgba(188,219,5,.08),transparent 70%)}
.dc-eye{font-size:.64rem;font-weight:700;text-transform:uppercase;letter-spacing:.14em;color:var(--lime);margin-bottom:16px}
.dc-title{font-family:var(--syne);font-size:1.25rem;font-weight:800;color:white;margin-bottom:10px;line-height:1.2}
.dc-desc{font-size:.8rem;color:rgba(255,255,255,.45);line-height:1.75;margin-bottom:24px}
.dc-items{display:flex;flex-direction:column;gap:10px;margin-bottom:24px}
.dc-item{display:flex;gap:10px;align-items:flex-start}
.dc-chk{width:18px;height:18px;border-radius:50%;background:rgba(188,219,5,.15);display:flex;align-items:center;justify-content:center;font-size:.5rem;color:var(--lime);font-weight:700;flex-shrink:0;margin-top:2px}
.dc-item p{font-size:.77rem;color:rgba(255,255,255,.5);line-height:1.55}
.dc-bar{padding-top:20px;border-top:1px solid rgba(255,255,255,.07)}
.dcb-label{font-size:.64rem;color:rgba(255,255,255,.3);margin-bottom:6px;text-transform:uppercase;letter-spacing:.1em}
.dcb-track{height:4px;background:rgba(255,255,255,.07);border-radius:2px;margin-bottom:10px;overflow:hidden}
.dcb-fill{height:100%;background:linear-gradient(90deg,var(--green),var(--lime-d));border-radius:2px;width:0;transition:width 1.6s cubic-bezier(.25,1,.5,1)}
.dif-text{}
.dif-text .eyebrow{color:var(--green)}
.dif-text .eyebrow::before{background:var(--green)}
.dif-text h2{margin-bottom:8px}
.dif-text .lead{margin-bottom:28px}
.dif-pills{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:28px}
.dpill{background:var(--off);border:1px solid var(--border);color:var(--muted);font-size:.72rem;font-weight:600;padding:6px 14px;border-radius:100px;transition:all .2s}
.dpill:hover{background:var(--lime-l);border-color:var(--lime-d);color:var(--green)}
.dif-callout{background:var(--off);border:1px solid var(--border);border-left:3px solid var(--lime-d);border-radius:0 12px 12px 0;padding:18px 20px}
.dif-callout p{font-size:.83rem;color:var(--muted);line-height:1.75}
.dif-callout strong{color:var(--text)}

/* ===================== COMO FUNCIONA ===================== */
#como{background:var(--dark)}
#como .eyebrow{color:var(--lime)}
#como .h2{color:var(--white)}
#como .lead{color:rgba(255,255,255,.4)}
.como-layout{display:grid;grid-template-columns:1fr 2fr;gap:80px;align-items:start}
.como-left .lead{max-width:300px}
.como-steps{display:flex;flex-direction:column;gap:0}
.cs{display:grid;grid-template-columns:44px 1fr;gap:22px;padding:26px 0;border-bottom:1px solid rgba(255,255,255,.05);position:relative}
.cs:last-child{border-bottom:none}
.cs-n{font-family:var(--mono);font-size:.68rem;color:var(--lime);letter-spacing:.1em;min-width:0;padding-top:5px}
.cs-body h4{font-family:var(--syne);font-size:1.08rem;font-weight:800;color:var(--white);margin-bottom:6px;line-height:1.16}
.cs-body p{font-size:.84rem;color:rgba(255,255,255,.43);line-height:1.68}
.cs-tag{display:inline-flex;margin-top:8px;background:rgba(188,219,5,.08);border:1px solid rgba(188,219,5,.15);color:var(--lime);font-size:.6rem;font-weight:700;padding:2px 9px;border-radius:100px;letter-spacing:.07em}

/* ===================== SUCCESS FEE ===================== */
#fee{background:var(--off)}
.fee-layout{display:grid;grid-template-columns:1fr 1fr;gap:72px;align-items:center}
.fee-vis{background:var(--white);border:1px solid var(--border);border-radius:20px;padding:36px;position:relative;overflow:hidden}
.fee-vis::before{content:'';position:absolute;top:0;right:0;width:100px;height:100px;background:radial-gradient(rgba(188,219,5,.12),transparent 70%)}
.fv-head{display:flex;align-items:center;gap:12px;margin-bottom:28px}
.fv-icon{width:44px;height:44px;border-radius:12px;background:var(--lime);display:flex;align-items:center;justify-content:center;font-size:1.2rem}
.fv-title{font-family:var(--syne);font-size:1.05rem;font-weight:800;color:var(--text)}
.fv-title span{display:block;font-size:.7rem;font-weight:500;color:var(--muted);margin-top:1px}
.fee-steps{display:flex;flex-direction:column;gap:0;position:relative}
.fee-steps::before{content:'';position:absolute;left:16px;top:20px;bottom:20px;width:1px;background:var(--border)}
.fs{display:flex;gap:14px;padding:14px 0}
.fs-dot{width:33px;height:33px;border-radius:50%;background:var(--green);display:flex;align-items:center;justify-content:center;font-size:.7rem;font-weight:800;color:white;flex-shrink:0;position:relative;z-index:1;border:3px solid var(--white)}
.fs-body h4{font-size:.82rem;font-weight:700;color:var(--text);margin-bottom:2px}
.fs-body p{font-size:.74rem;color:var(--muted);line-height:1.55}
.fee-note{margin-top:22px;background:var(--lime-l);border:1px solid rgba(188,219,5,.25);border-radius:10px;padding:14px 16px;font-size:.78rem;color:var(--green);font-weight:600;line-height:1.5}
.fee-text h2{margin-bottom:8px}
.fee-text .lead{margin-bottom:28px}
.fee-list{display:flex;flex-direction:column;gap:14px}
.fl{display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:12px;transition:all .2s}
.fl:hover{border-color:var(--lime-d);background:var(--lime-l)}
.fl-ic{font-size:1.1rem;flex-shrink:0;margin-top:2px}
.fl h4{font-family:var(--syne);font-size:.83rem;font-weight:700;color:var(--text);margin-bottom:2px}
.fl p{font-size:.74rem;color:var(--muted);line-height:1.5}

/* ===================== MARKET INTEL ===================== */
#inteligencia{background:var(--dark2)}
.intel-top{display:flex;justify-content:space-between;align-items:flex-end;flex-wrap:wrap;gap:20px;margin-bottom:60px}
#inteligencia .eyebrow{color:var(--lime)}
#inteligencia .h2{color:var(--white)}
.intel-right{font-size:.88rem;color:rgba(255,255,255,.35);line-height:1.75;max-width:400px}
.intel-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:52px}
.ig{background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.06);border-radius:var(--r2);padding:28px 24px;transition:all .25s;cursor:default}
.ig:hover{background:rgba(255,255,255,.05);border-color:rgba(188,219,5,.2)}
.ig-icon{font-size:1.4rem;margin-bottom:14px}
.ig h3{font-family:var(--syne);font-size:.9rem;font-weight:700;color:rgba(255,255,255,.8);margin-bottom:7px;line-height:1.3}
.ig p{font-size:.76rem;color:rgba(255,255,255,.35);line-height:1.65}
.intel-callout{background:rgba(188,219,5,.04);border:1px solid rgba(188,219,5,.12);border-radius:var(--r2);padding:36px;display:grid;grid-template-columns:1fr auto 1fr;gap:36px;align-items:center}
.icl-metrics{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.icl-m{background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.06);border-radius:12px;padding:18px 20px}
.icl-m-highlight{background:rgba(188,219,5,.06);border-color:rgba(188,219,5,.2)}
.icl-val{font-family:var(--syne);font-size:2.2rem;font-weight:800;color:var(--white);line-height:1;letter-spacing:-.04em}
.icl-val span{color:var(--lime);font-size:1.4rem}
.icl-val-sm{font-family:var(--syne);font-size:1.1rem;font-weight:800;color:var(--lime);line-height:1.2;margin-bottom:4px}
.icl-lab{font-size:.68rem;color:rgba(255,255,255,.35);margin-top:6px;line-height:1.4}
.icl-divider{width:1px;background:rgba(255,255,255,.08);align-self:stretch}
.icl-text{}
.icl-tag{font-size:.62rem;font-weight:700;text-transform:uppercase;letter-spacing:.14em;color:var(--lime-d);margin-bottom:14px}
.icl-text p{font-size:.86rem;color:rgba(255,255,255,.45);line-height:1.85}
.icl-text strong{color:rgba(255,255,255,.8)}
@media(max-width:1024px){.intel-callout{grid-template-columns:1fr;gap:24px}.icl-divider{width:100%;height:1px}}
@media(max-width:480px){.icl-metrics{grid-template-columns:1fr 1fr}}

/* ===================== SERVICES ===================== */
#servicos{background:var(--white)}
.svc-top{display:flex;justify-content:space-between;align-items:flex-end;flex-wrap:wrap;gap:16px;margin-bottom:52px}
.svc-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
.sv{background:var(--off);border:1px solid var(--border);border-radius:var(--r2);padding:32px 28px;transition:all .25s;cursor:default;position:relative;overflow:hidden;display:grid;grid-template-columns:auto 1fr;grid-template-areas:"num num" "icon title" "text text" "tags tags";column-gap:18px;align-items:center}
.sv::after{content:'';position:absolute;top:0;right:0;width:60px;height:60px;background:radial-gradient(rgba(0,96,42,.06),transparent 70%);transition:all .35s}
.sv:hover{border-color:var(--lime-d);box-shadow:0 12px 36px rgba(0,0,0,.06);transform:translateY(-3px)}
.sv:hover::after{width:120px;height:120px}
.sv-n{grid-area:num;font-family:var(--mono);font-size:.58rem;color:#bdb9ad;letter-spacing:.1em;margin-bottom:24px}
.sv-ic{grid-area:icon;font-size:2.35rem;line-height:1;margin-bottom:0}
.sv h3{grid-area:title;font-family:var(--syne);font-size:clamp(1.18rem,1.5vw,1.45rem);font-weight:800;color:var(--green);margin-bottom:0;line-height:1.08;text-wrap:balance}
.sv p{grid-area:text;font-size:.88rem;color:var(--muted);line-height:1.75;margin:18px 0 16px;max-width:64ch}
.sv-tags{grid-area:tags;display:flex;flex-wrap:wrap;gap:7px}
.sv-tag{font-size:.62rem;font-weight:600;color:var(--muted);background:var(--white);border:1px solid var(--border);padding:3px 9px;border-radius:100px}

/* ===================== GESTAO CONTINUA / ENTREGAS ===================== */
#gestao-mensal{background:var(--off)}
.gm-layout{display:grid;grid-template-columns:.95fr 1.05fr;gap:64px;align-items:start}
.gm-panel{background:var(--dark);border-radius:20px;padding:34px;position:sticky;top:96px;overflow:hidden}
.gm-panel::after{content:'';position:absolute;right:-80px;top:-80px;width:220px;height:220px;background:radial-gradient(rgba(188,219,5,.12),transparent 70%);pointer-events:none}
.gm-panel .eyebrow{color:var(--lime)}
.gm-panel .eyebrow::before{background:var(--lime)}
.gm-panel h2{color:var(--white);margin-bottom:14px}
.gm-panel p{font-size:.9rem;color:rgba(255,255,255,.54);line-height:1.8;margin-bottom:22px}
.gm-panel strong{color:var(--lime)}
.gm-list{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.gm-card{background:var(--white);border:1px solid var(--border);border-radius:14px;padding:20px;transition:all .22s;display:grid;grid-template-columns:auto 1fr;grid-template-areas:"num title" "text text";gap:11px 13px;align-items:center}
.gm-card:hover{border-color:var(--lime-d);box-shadow:0 10px 28px rgba(0,96,42,.07);transform:translateY(-2px)}
.gm-card span{grid-area:num;display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;border-radius:8px;background:var(--lime-l);color:var(--green);font-size:.72rem;font-weight:800;margin-bottom:0}
.gm-card h3{grid-area:title;font-family:var(--syne);font-size:1rem;font-weight:800;line-height:1.18;margin-bottom:0;color:var(--text)}
.gm-card p{grid-area:text;font-size:.78rem;color:var(--muted);line-height:1.6}
.scope-box{margin-top:18px;background:var(--white);border:1px solid var(--border);border-left:3px solid var(--green);border-radius:0 14px 14px 0;padding:22px}
.scope-box h3{font-family:var(--syne);font-size:1rem;color:var(--green);margin-bottom:12px}
.scope-tags{display:flex;flex-wrap:wrap;gap:7px}
.scope-tags span{font-size:.68rem;font-weight:600;color:var(--muted);background:var(--off);border:1px solid var(--border);padding:5px 10px;border-radius:100px}

/* ===================== CLIENTS ===================== */
#clientes{background:var(--off)}
.cl-top{text-align:center;margin-bottom:52px}
.cl-top .eyebrow{justify-content:center}
.cl-top .eyebrow::before{display:none}
.cl-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:36px}
.clc{background:var(--white);border:1px solid var(--border);border-radius:var(--r2);padding:22px;text-align:center;transition:all .25s;cursor:default}
.clc:hover{border-color:var(--green);transform:translateY(-3px);box-shadow:0 8px 24px rgba(0,96,42,.08)}
.clc-name{font-family:var(--syne);font-size:.88rem;font-weight:700;color:var(--text);margin-bottom:5px}
.clc-since{font-size:.68rem;color:var(--lime-d);font-weight:600;margin-bottom:4px}
.clc-units{font-size:.7rem;color:var(--muted)}
.cl-bottom{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.clb{background:var(--dark);border-radius:var(--r2);padding:28px;text-align:center}
.clb-val{font-family:var(--syne);font-size:2.2rem;font-weight:800;color:var(--white);line-height:1;margin-bottom:6px}
.clb-val em{color:var(--lime);font-style:normal}
.clb-l{font-size:.74rem;color:rgba(255,255,255,.35);line-height:1.4}

/* ===================== HUMANIZADO ===================== */
#humanizado{background:var(--green);padding:100px 0}
.hum-layout{display:grid;grid-template-columns:1fr 1fr;gap:72px;align-items:center}
.hum-text .eyebrow{color:var(--lime)}
.hum-text .eyebrow::before{background:var(--lime)}
.hum-text h2{color:var(--white);margin-bottom:12px}
.hum-text .lead{color:rgba(255,255,255,.55);margin-bottom:28px}
.hum-pts{display:flex;flex-direction:column;gap:14px}
.hp{display:flex;gap:13px;align-items:flex-start;padding:16px 18px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);border-radius:12px;transition:all .2s}
.hp:hover{background:rgba(255,255,255,.11)}
.hp-ic{font-size:1rem;flex-shrink:0;margin-top:2px}
.hp h4{font-size:.83rem;font-weight:700;color:var(--white);margin-bottom:2px}
.hp p{font-size:.74rem;color:rgba(255,255,255,.5);line-height:1.5}
.hum-vis{background:rgba(0,0,0,.15);border:1px solid rgba(255,255,255,.1);border-radius:20px;padding:32px}
.hv-title{font-family:var(--syne);font-size:.82rem;font-weight:700;color:rgba(255,255,255,.5);text-transform:uppercase;letter-spacing:.1em;margin-bottom:20px}
.hv-compare{display:flex;flex-direction:column;gap:10px}
.hvc{display:flex;gap:12px;padding:14px 16px;border-radius:10px;align-items:flex-start}
.hvc.bad{background:rgba(239,68,68,.08);border:1px solid rgba(239,68,68,.15)}
.hvc.good{background:rgba(188,219,5,.08);border:1px solid rgba(188,219,5,.2)}
.hvc-label{font-size:.62rem;font-weight:700;padding:3px 8px;border-radius:100px;flex-shrink:0;margin-top:2px;letter-spacing:.06em;white-space:nowrap}
.hvc.bad .hvc-label{background:rgba(239,68,68,.2);color:#fca5a5}
.hvc.good .hvc-label{background:rgba(188,219,5,.2);color:var(--lime)}
.hvc p{font-size:.77rem;line-height:1.55}
.hvc.bad p{color:rgba(255,255,255,.4)}
.hvc.good p{color:rgba(255,255,255,.7)}

/* ===================== RESULTS ===================== */
#resultados{background:var(--dark3)}
#resultados .eyebrow{color:var(--lime)}
#resultados .h2{color:var(--white)}
.res-layout{display:grid;grid-template-columns:1fr 1fr;gap:72px;align-items:center;margin-top:52px}
.res-bars{display:flex;flex-direction:column;gap:22px}
.rb{cursor:default}
.rb-head{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:7px}
.rb-l{font-size:.8rem;font-weight:500;color:rgba(255,255,255,.6)}
.rb-v{font-family:var(--mono);font-size:.8rem;font-weight:500;color:var(--lime)}
.rb-track{height:4px;background:rgba(255,255,255,.06);border-radius:2px;overflow:hidden}
.rb-fill{height:100%;background:linear-gradient(90deg,var(--green),var(--lime-d));border-radius:2px;width:0;transition:width 1.6s cubic-bezier(.25,1,.5,1)}
.res-text h3{font-family:var(--syne);font-size:clamp(1.4rem,2.4vw,2rem);font-weight:800;color:var(--white);line-height:1.2;letter-spacing:-.025em;margin-bottom:20px}
.ri-list{display:flex;flex-direction:column;gap:14px}
.ri{display:flex;gap:11px;align-items:flex-start}
.ri-chk{width:20px;height:20px;border-radius:50%;background:rgba(188,219,5,.12);display:flex;align-items:center;justify-content:center;font-size:.52rem;color:var(--lime);font-weight:700;flex-shrink:0;margin-top:1px}
.ri p{font-size:.8rem;color:rgba(255,255,255,.45);line-height:1.65}
.ri p strong{color:rgba(255,255,255,.8)}

/* ===================== FAQ ===================== */
#faq{background:var(--off)}
.faq-layout{display:grid;grid-template-columns:1fr 2fr;gap:72px}
.faq-left p{font-size:.87rem;color:var(--muted);line-height:1.8;margin-top:14px}
.faq-list{display:flex;flex-direction:column}
.fq{border-bottom:1px solid var(--border)}
.fq-q{display:flex;justify-content:space-between;align-items:center;padding:20px 0;cursor:pointer;gap:14px}
.fq-t{font-family:var(--syne);font-size:.9rem;font-weight:600;color:var(--text)}
.fq-ic{width:24px;height:24px;border-radius:50%;border:1.5px solid var(--border);display:flex;align-items:center;justify-content:center;font-size:1rem;color:var(--muted);transition:all .2s;flex-shrink:0}
.fq.open .fq-ic{background:var(--green);border-color:var(--green);color:white;transform:rotate(45deg)}
.fq-a{max-height:0;overflow:hidden;transition:max-height .4s ease}
.fq-a-in{padding:0 0 18px;font-size:.81rem;color:var(--muted);line-height:1.8}

/* ===================== CTA ===================== */
#contato{background:var(--dark);padding:140px 0;text-align:center;position:relative;overflow:hidden}
#contato::before{content:'';position:absolute;top:-150px;left:50%;transform:translateX(-50%);width:800px;height:800px;border-radius:50%;background:radial-gradient(circle,rgba(188,219,5,.04) 0%,transparent 60%)}
#contato::after{content:'';position:absolute;bottom:-100px;left:0;right:0;height:300px;background:radial-gradient(ellipse at 30% 100%,rgba(0,96,42,.15),transparent 60%)}
.cta-inner{position:relative;z-index:1}
.cta-pre{font-family:var(--mono);font-size:.64rem;font-weight:500;color:var(--lime);text-transform:uppercase;letter-spacing:.16em;margin-bottom:20px}
.cta-h2{font-family:var(--syne);font-size:clamp(2.2rem,5.5vw,4.4rem);font-weight:800;color:var(--white);line-height:1.04;letter-spacing:-.045em;max-width:700px;margin:0 auto 18px}
.cta-h2 .out{color:rgba(255,255,255,.35)}
.cta-h2 .acc{color:var(--lime)}
.cta-p{font-size:.95rem;color:rgba(255,255,255,.38);max-width:480px;margin:0 auto 44px;line-height:1.8}
.cta-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;max-width:700px;margin:0 auto 44px}
.cc{background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.07);border-radius:14px;padding:20px;text-align:center}
.cc-icon{font-size:1.4rem;margin-bottom:8px}
.cc-t{font-size:.76rem;font-weight:600;color:rgba(255,255,255,.65);line-height:1.4}
.cta-btns{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
.cta-note{font-size:.7rem;color:rgba(255,255,255,.2);margin-top:22px}

/* HERO DISCLAIMER */
.hv-disclaimer{display:inline-flex;align-items:center;gap:6px;font-family:var(--mono);font-size:.58rem;color:rgba(255,255,255,.22);letter-spacing:.08em;margin-bottom:10px;margin-top:10px}
.hv-disclaimer::before{content:'';display:inline-block;width:14px;height:1px;background:rgba(255,255,255,.15)}
.hv-disclaimer::after{content:'';display:inline-block;width:14px;height:1px;background:rgba(255,255,255,.15)}

/* ===================== LOGOS ===================== */
#logos{background:var(--off);padding:64px 0;border-bottom:1px solid var(--border)}
.logos-head{text-align:center;margin-bottom:36px}
.logos-eyebrow{display:inline-flex;align-items:center;justify-content:center;gap:9px;font-size:.62rem;font-weight:700;text-transform:uppercase;letter-spacing:.16em;color:var(--muted);margin-bottom:0}
.logos-track-wrap{overflow:hidden;position:relative}
.logos-track-wrap::before,.logos-track-wrap::after{content:'';position:absolute;top:0;bottom:0;width:120px;z-index:2;pointer-events:none}
.logos-track-wrap::before{left:0;background:linear-gradient(90deg,var(--off),transparent)}
.logos-track-wrap::after{right:0;background:linear-gradient(-90deg,var(--off),transparent)}
.logos-track{display:flex;align-items:center;gap:0;white-space:nowrap}
.logos-belt{display:inline-flex;align-items:center;gap:0;animation:logoScroll 32s linear infinite}
.logos-belt:hover{animation-play-state:paused}
.logo-item{display:inline-flex;align-items:center;justify-content:center;padding:0 36px;height:64px;border-right:1px solid var(--border);flex-shrink:0}
.logo-item:last-child{border-right:none}
.logo-item img{max-height:42px;max-width:140px;width:auto;height:auto;object-fit:contain;transition:opacity .3s}
.logo-item:hover img{opacity:.75}
@keyframes logoScroll{from{transform:translateX(0)}to{transform:translateX(-50%)}}

/* ===================== FORM WIX ===================== */
.cta-form-wrap{max-width:1040px;margin:0 auto;text-align:left;border-radius:20px;overflow:hidden;background:#071306;box-shadow:0 24px 70px rgba(0,0,0,.24)}
#wix-form-iframe{display:block;width:100%;height:700px;min-height:700px;border:0;border-radius:20px;background:#071306;overflow:hidden}
.cf-privacy{text-align:center;font-size:.69rem;color:rgba(255,255,255,.2);margin-top:16px;letter-spacing:.01em}
.form-hint{max-width:1040px;margin:0 auto 12px;text-align:center;font-size:.76rem;color:rgba(255,255,255,.42);line-height:1.5}
@media(max-width:1120px){
  .cta-form-wrap{max-width:100%;overflow:hidden}
  #wix-form-iframe{width:100%;max-width:100%;height:720px;min-height:720px}
}
@media(max-width:1180px){
  .nav-contact{display:none}
  .nav-links a{padding:0 10px;font-size:.7rem}
}
@media(max-width:980px){
  #nav .nav-links{display:none}
  .nav-mob{display:block}
}
@media(max-width:580px){
  .cta-form-wrap{max-width:100%;border-radius:14px}
  #wix-form-iframe{height:820px;min-height:820px;border-radius:14px}
}

/* FOOTER */
footer{background:var(--dark);border-top:1px solid rgba(255,255,255,.05);padding:28px 5%;padding-bottom:calc(28px + env(safe-area-inset-bottom,0px));display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:14px}
.ft-brand{display:flex;align-items:center;gap:14px;flex-wrap:wrap}
.ft-brand img{height:40px;width:auto;object-fit:contain;filter:brightness(0) invert(1);opacity:.62}
.ft-brand img.logo-acp{height:32px}
.ft-brand span{width:1px;height:34px;background:rgba(255,255,255,.14)}
.ft-info{max-width:760px;text-align:right}
footer p{font-size:.68rem;color:rgba(255,255,255,.28);line-height:1.65}
.float-wa{position:fixed;right:22px;bottom:calc(22px + env(safe-area-inset-bottom,0px));z-index:320;display:inline-flex;align-items:center;justify-content:center;width:58px;height:58px;background:#25d366;color:#fff;border-radius:999px;box-shadow:0 14px 34px rgba(37,211,102,.32);transition:transform .22s,box-shadow .22s}
.float-wa.is-embed-fixed{position:absolute;top:var(--float-wa-top,22px);bottom:auto}
.float-wa svg{width:30px;height:30px;display:block;fill:currentColor}
.float-wa:hover{transform:translateY(-2px);box-shadow:0 18px 42px rgba(37,211,102,.34)}
.float-wa:active{transform:translateY(0)}

/* ANIMATIONS */
@keyframes fadeUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.45}}
@keyframes tick{from{transform:translateX(0)}to{transform:translateX(-50%)}}

/* RESPONSIVE */
@media(max-width:1024px){
  .hero-wrap{grid-template-columns:1fr}.hero-vis{display:none}
  .pain-head{grid-template-columns:1fr;gap:16px}
  .dif-layout,.fee-layout,.hum-layout,.res-layout,.faq-layout,.gm-layout{grid-template-columns:1fr}
  .gm-panel{position:relative;top:auto}
  .como-layout{grid-template-columns:1fr;gap:36px}
  .intel-grid{grid-template-columns:1fr 1fr}
  .intel-callout{grid-template-columns:1fr}
  .cl-grid{grid-template-columns:1fr 1fr}
  .cl-bottom{grid-template-columns:1fr 1fr}
  .svc-grid{grid-template-columns:1fr}
  .tem-inner{grid-template-columns:1fr}
  .cta-cards{grid-template-columns:1fr}
  footer{flex-direction:column;text-align:center}
  .ft-info{text-align:center}
}
@media(max-width:768px){
  .sec{padding:72px 0}
  #hero{min-height:auto;padding:92px 0 44px}
  #nav .nav-links{display:none}
  .nav-mob{display:block}
  #nav{height:76px;padding:0 18px}
  #nav::before{inset:10px 12px}
  .nav-logo{gap:12px;padding-left:8px}
  .nav-logo img{height:40px}.nav-logo img.logo-acp{height:32px}.nav-contact{display:none}
  .nav-logo-divider{height:34px}
  .pain-grid{grid-template-columns:1fr}
  .cl-grid{grid-template-columns:1fr 1fr}
  .intel-grid{grid-template-columns:1fr}
  .cl-bottom{grid-template-columns:1fr}
  .hero-stats{grid-template-columns:1fr 1fr 1fr}
  .cta-h2{font-size:clamp(1.9rem,9vw,3.2rem)}
  .brand-pair{padding:11px 14px;margin-bottom:18px}
  .brand-pair img{height:36px}.brand-pair img.logo-acp{height:29px}
}
@media(max-width:480px){
  .pain-grid{grid-template-columns:1fr}
  .hero-acts{flex-direction:column}
  .hero-acts .btn,.hero-acts .btn-ow{width:100%;justify-content:center}
  .cl-grid{grid-template-columns:1fr}
  .hero-stats{grid-template-columns:1fr 1fr}
  .cta-btns{flex-direction:column;align-items:center}
  .cta-btns .btn,.cta-btns .btn-ow{width:100%;max-width:320px;justify-content:center}
  .pain-highlight{flex-direction:column;gap:16px}
  .gm-list{grid-template-columns:1fr}
  .float-wa{right:14px;bottom:calc(14px + env(safe-area-inset-bottom,0px));width:52px;height:52px}
  .float-wa svg{width:27px;height:27px}
}

/* ===================== MOBILE FIXES — scroll, form e alinhamento ===================== */

/* Conter overflow das animações de reveal sem quebrar position:sticky do .gm-panel */
section{overflow-x:clip}
#hero,.tem-band,#contato{overflow:hidden}

/* ---- 1024px: botão gm-panel e callout ---- */
@media(max-width:1024px){
  .gm-panel{padding:26px 22px}
  .gm-panel .btn{width:100%;justify-content:center;box-sizing:border-box}
  .icl-text p,.icl-text strong{overflow-wrap:break-word;word-break:break-word}
  .intel-callout{padding:28px 22px}
}

/* ---- 768px: hero badge, comparativo empilhado, paddings ---- */
@media(max-width:768px){
  #contato{padding:84px 0}
  .hero-pre{border-radius:10px;white-space:normal;text-align:left}
  .dif-card{padding:24px 20px}
  .hum-vis{padding:24px 20px}
  /* Comparativo ACOPLA vs Plataformas:
     empilha label acima do texto — muito mais legível em coluna única */
  .hvc{flex-direction:column;gap:6px;padding:16px}
  .hvc-label{white-space:normal;align-self:flex-start;font-size:.65rem}
  .hvc p{font-size:.84rem;line-height:1.65}
}

/* ---- 580px: form sai do padding do .w para usar largura total do viewport ---- */
@media(max-width:580px){
  /* margin negativa compensa o padding de 5% do container .w,
     dando ao iframe a largura total da tela */
  .cta-form-wrap{
    margin-left:-5vw;
    margin-right:-5vw;
    width:auto;
    max-width:none;
    border-radius:0;
  }
  #wix-form-iframe{
    border-radius:0;
    width:100%;
    height:940px;
    min-height:940px;
  }
  /* Callout de métricas: reduz gap e fonte para caber em telas estreitas */
  .intel-callout{overflow:hidden;padding:20px 16px}
  .icl-metrics{gap:10px}
  .icl-m{padding:14px 12px}
  .icl-val{font-size:1.8rem}
  .icl-val span{font-size:1.2rem}
  .icl-val-sm{font-size:.95rem}
}

/* ---- 480px: ajustes finos de padding e tamanho ---- */
@media(max-width:480px){
  #contato{padding:60px 0}
  .brand-pair{padding:10px 12px;gap:8px}
  .brand-pair img{height:30px}
  .brand-pair img.logo-acp{height:24px}
  .pain-highlight{padding:22px 16px}
  .fee-vis{padding:24px 18px}
  .scope-box{padding:18px 14px}
  .cs-tag{white-space:normal;line-height:1.5}
  /* Métricas ainda menores em telas muito pequenas */
  .icl-val{font-size:1.55rem}
  .icl-m{padding:12px 10px}
  .icl-metrics{gap:8px}
  #wix-form-iframe{height:980px;min-height:980px}
  #nav{height:70px;padding:0 12px}
  #nav::before{inset:8px}
  .nav-logo img{height:34px}
  .nav-logo img.logo-acp{height:27px}
  .nav-logo-divider{height:28px}
  .nav-mob{padding:8px 12px;font-size:.72rem}
}

/* ===================== HORIZONTAL READING STRUCTURE ===================== */
@media (min-width:1025px){
  .w{max-width:1320px}
  .sec{padding:92px 0}

  .pain-head{display:grid;grid-template-columns:minmax(340px,.86fr) minmax(480px,1.14fr);align-items:center;gap:64px;margin-bottom:38px;text-align:left}
  .pain-head [data-r]{align-items:flex-start}
  .pain-head .eyebrow{justify-content:flex-start}
  .pain-head .eyebrow::before{display:inline-block}
  .pain-right-text{max-width:760px;margin:0;text-align:left;font-size:clamp(1.04rem,1.25vw,1.22rem)}
  .pain-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;overflow:visible;padding-bottom:0}
  .pain-card{min-height:250px}

  #quote-banner{padding:70px 0}
  .qb-inner{max-width:1180px;display:grid;grid-template-columns:110px minmax(420px,1.05fr) minmax(280px,.8fr);align-items:center;gap:32px;text-align:left}
  .qb-mark,.qb-text,.qb-sub{margin:0}
  .qb-mark{font-size:7rem;line-height:.82}

  .dif-layout{grid-template-columns:minmax(420px,.95fr) minmax(520px,1.05fr);gap:54px}
  .dc-items{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
  .dc-item{align-items:flex-start;padding:12px;border:1px solid rgba(255,255,255,.07);border-radius:12px;background:rgba(255,255,255,.035)}
  .dif-callout{display:grid;grid-template-columns:minmax(220px,.78fr) minmax(300px,1.22fr);align-items:center}

  .como-layout{grid-template-columns:1fr;gap:30px}
  .como-left{display:grid;grid-template-columns:minmax(360px,.86fr) minmax(420px,1.14fr);grid-template-areas:"eyebrow lead" "title lead" "button lead";align-items:end;gap:12px 44px}
  .como-left .eyebrow{grid-area:eyebrow}
  .como-left .h2{grid-area:title;max-width:690px}
  .como-left .lead{grid-area:lead;margin:0;max-width:560px}
  .como-left .btn{grid-area:button;justify-self:start}
  .como-left br{display:none}
  .como-steps{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px;overflow:visible;padding-bottom:0}
  .cs{display:flex;flex-direction:column;min-height:320px;padding:18px;border:1px solid rgba(255,255,255,.08);border-radius:14px;background:rgba(255,255,255,.035)}
  .cs-tag{margin-top:auto;white-space:normal}

  .fee-layout{grid-template-columns:minmax(520px,1fr) minmax(460px,.9fr);gap:48px;align-items:start}
  .fee-steps{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
  .fee-steps::before{display:none}
  .fs{display:grid;grid-template-columns:auto 1fr;align-items:start;gap:10px;padding:14px;border:1px solid var(--border);border-radius:12px;background:var(--off)}
  .fs h3{margin-top:.15rem}
  .fs p{grid-column:1/-1}
  .fee-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;overflow:visible;padding-bottom:0}
  .fl{min-height:120px;align-items:flex-start}

  .intel-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
  .ig{display:grid;grid-template-columns:auto 1fr;grid-template-areas:"icon title" "text text";align-items:center;gap:12px 14px;padding:20px}
  .ig-icon{grid-area:icon;margin:0;font-size:1.75rem}
  .ig h3{grid-area:title;margin:0;font-size:1.02rem}
  .ig p{grid-area:text;margin:0}
  .intel-callout{grid-template-columns:minmax(360px,.9fr) auto minmax(480px,1.1fr)}
  .icl-metrics{grid-template-columns:repeat(3,minmax(0,1fr))}

  .svc-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;overflow:visible;padding-bottom:0}
  .sv{min-height:270px}

  .gm-layout{grid-template-columns:minmax(380px,.7fr) minmax(0,1.3fr);gap:42px}
  .gm-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;overflow:visible;padding-bottom:0}
  .gm-card{min-height:215px}
  .scope-box{display:grid;grid-template-columns:260px 1fr;align-items:start;gap:20px}
  .scope-box h3{margin:0}

  #clientes .w{display:grid;grid-template-columns:minmax(320px,.6fr) minmax(0,1.4fr);grid-template-areas:"head clients" "metrics metrics";align-items:center;gap:28px 40px}
  .cl-top{grid-area:head;align-self:center;margin:0;text-align:left}
  .cl-top .eyebrow{justify-content:flex-start}
  .cl-top .eyebrow::before{display:inline-block}
  .cl-grid{grid-area:clients;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:0;overflow:visible;padding-bottom:0}
  .clc{text-align:left}
  .cl-bottom{grid-area:metrics;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:0}
  .clb{display:grid;grid-template-columns:auto 1fr;align-items:center;gap:12px;text-align:left}

  .hum-layout{grid-template-columns:minmax(420px,.9fr) minmax(520px,1.1fr);gap:46px}
  .hum-pts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
  .hp{display:grid;grid-template-columns:auto 1fr;grid-template-areas:"icon title" "text text";align-items:center;gap:10px 12px;padding:16px}
  .hp-ic{grid-area:icon;margin:0;font-size:1.45rem}
  .hp h4{grid-area:title;font-size:.96rem}
  .hp p{grid-area:text}
  .hv-compare{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
  .hvc{display:grid;grid-template-columns:auto 1fr;align-items:start;gap:10px}

  .res-layout{grid-template-columns:minmax(500px,1fr) minmax(460px,.9fr);gap:44px}
  .res-bars{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
  .rb{padding:16px;border:1px solid rgba(255,255,255,.07);border-radius:12px;background:rgba(255,255,255,.035)}
  .ri-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
  .ri{align-items:flex-start}

  .faq-layout{grid-template-columns:minmax(300px,.6fr) minmax(0,1.4fr);gap:42px}
  .faq-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
  .fq{padding:0 18px;border:1px solid var(--border);border-radius:14px;background:var(--white)}
  .fq-q{border-bottom:0}

  #contato{padding:112px 0;text-align:left}
  .cta-inner{display:grid;grid-template-columns:minmax(360px,.82fr) minmax(560px,1.18fr);grid-template-areas:"pre form" "title form" "text form" "cards form" "buttons form" "hint form";align-items:start;gap:16px 54px}
  .cta-pre{grid-area:pre;margin:0}
  .cta-h2{grid-area:title;max-width:none;margin:0;font-size:clamp(2.1rem,4.6vw,4rem)}
  .cta-p{grid-area:text;max-width:none;margin:0 0 12px}
  .cta-cards{grid-area:cards;max-width:none;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:0}
  .cc{display:grid;grid-template-columns:auto 1fr;align-items:center;gap:10px;padding:16px;text-align:left}
  .cc-icon{margin:0}
  .cta-btns{grid-area:buttons;justify-content:flex-start;margin:0 !important}
  .form-hint{grid-area:hint;margin:0;text-align:left}
  .cta-form-wrap{grid-area:form;max-width:none;margin:0}
}

@media (min-width:1025px) and (max-width:1180px){
  .pain-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .como-left{grid-template-columns:1fr;grid-template-areas:"eyebrow" "title" "lead" "button";gap:12px}
  .como-steps{grid-template-columns:repeat(3,minmax(0,1fr))}
  .fee-layout,.gm-layout,.hum-layout,.res-layout,.faq-layout{grid-template-columns:1fr}
  .intel-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
  .cl-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .cta-inner{grid-template-columns:1fr;grid-template-areas:"pre" "title" "text" "cards" "buttons" "form" "hint"}
}

@media (max-width:1024px){
  #contato{text-align:center}
  .cta-inner{display:block}
  .form-hint{text-align:center}
}`;

