const template = document.createElement('template');
template.innerHTML = '<style>' + ACOPLA_LP_STYLES + '</style><div class="acopla-lp-root">' + ACOPLA_LP_MARKUP + '</div>';

class AcoplaLandingPage extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this.shadowRoot.appendChild(template.content.cloneNode(true));
    this._observers = [];
    this._scrollHandler = null;
    this._messageHandler = null;
  }

  connectedCallback() {
    if (this._initialized) return;
    this._initialized = true;

    this.initScrollProgress();
    this.initNavScroll();
    this.initSmoothScroll();
    this.initReveal();
    this.initCounters();
    this.initBars();
    this.initWixFormHeight();
    this.initFaq();
    this.initFloatingWhatsapp();
  }

  disconnectedCallback() {
    if (this._scrollHandler) window.removeEventListener('scroll', this._scrollHandler);
    if (this._messageHandler) window.removeEventListener('message', this._messageHandler);
    this._observers.forEach((observer) => observer.disconnect());
    this._observers = [];
  }

  $(selector) {
    return this.shadowRoot.querySelector(selector);
  }

  $$(selector) {
    return Array.from(this.shadowRoot.querySelectorAll(selector));
  }

  initScrollProgress() {
    const sp = this.$('#sp');
    if (!sp) return;

    this._scrollHandler = () => {
      const scrollable = document.documentElement.scrollHeight - window.innerHeight;
      const pct = scrollable > 0 ? (window.scrollY / scrollable) * 100 : 0;
      sp.style.width = pct + '%';
    };

    window.addEventListener('scroll', this._scrollHandler, { passive: true });
    this._scrollHandler();
  }

  initNavScroll() {
    const nav = this.$('#nav');
    if (!nav) return;

    const updateNav = () => nav.classList.toggle('scrolled', window.scrollY > 50);
    window.addEventListener('scroll', updateNav, { passive: true });
    this._observers.push({ disconnect: () => window.removeEventListener('scroll', updateNav) });
    updateNav();
  }

  initSmoothScroll() {
    this.$$('a[href^="#"]').forEach((anchor) => {
      anchor.addEventListener('click', (event) => {
        const href = anchor.getAttribute('href');
        if (!href || href === '#') return;

        const target = this.shadowRoot.querySelector(href);
        if (target) {
          event.preventDefault();
          target.scrollIntoView({ behavior: 'smooth' });
        }
      });
    });
  }

  initReveal() {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add('on');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.1 });

    this.$$('[data-r]').forEach((el) => observer.observe(el));
    this._observers.push(observer);
  }

  animCounter(el, target, suffix) {
    const duration = 1800;
    const start = performance.now();

    const tick = (now) => {
      const progress = Math.min((now - start) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      el.textContent = Math.floor(eased * target) + (suffix || '');
      if (progress < 1) requestAnimationFrame(tick);
    };

    requestAnimationFrame(tick);
  }

  initCounters() {
    this.$$('[data-counter]').forEach((el) => {
      const target = parseInt(el.dataset.counter, 10);
      if (!Number.isFinite(target) || target === 0) return;
      this.animCounter(el, target, '');
    });
  }

  initBars() {
    const resSec = this.$('#res-sec');
    if (resSec) {
      const barObserver = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.querySelectorAll('.rb-fill, .dcb-fill').forEach((bar, index) => {
              setTimeout(() => { bar.style.width = bar.dataset.w + '%'; }, index * 130);
            });
            barObserver.unobserve(entry.target);
          }
        });
      }, { threshold: 0.2 });

      barObserver.observe(resSec);
      this._observers.push(barObserver);
    }

    const difCard = this.$('#dif-card');
    if (difCard) {
      const difObserver = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.querySelectorAll('.dcb-fill').forEach((bar, index) => {
              setTimeout(() => { bar.style.width = bar.dataset.w + '%'; }, index * 200 + 300);
            });
            difObserver.unobserve(entry.target);
          }
        });
      }, { threshold: 0.3 });

      difObserver.observe(difCard);
      this._observers.push(difObserver);
    }
  }

  initWixFormHeight() {
    this._messageHandler = (event) => {
      if (event.data && event.data.type === 'wix-form-height') {
        const iframe = this.$('#wix-form-iframe');
        if (iframe && event.data.height > 200) {
          iframe.style.minHeight = event.data.height + 'px';
          iframe.style.height = event.data.height + 'px';
        }
      }
    };

    window.addEventListener('message', this._messageHandler);
  }

  initFaq() {
    this.$$('.fq-q').forEach((question) => {
      question.addEventListener('click', () => {
        const item = question.parentElement;
        const answer = item.querySelector('.fq-a');
        const isOpen = item.classList.contains('open');

        this.$$('.fq').forEach((faqItem) => {
          faqItem.classList.remove('open');
          const faqAnswer = faqItem.querySelector('.fq-a');
          if (faqAnswer) faqAnswer.style.maxHeight = '0';
        });

        if (!isOpen && answer) {
          item.classList.add('open');
          answer.style.maxHeight = answer.scrollHeight + 'px';
        }
      });
    });
  }

  initFloatingWhatsapp() {
    const button = this.$('.float-wa');
    if (!button || window.parent === window) return;

    let parentWindow;
    let frame;
    try {
      parentWindow = window.parent;
      frame = window.frameElement;
      if (!parentWindow || !frame) return;
      void parentWindow.innerHeight;
      void frame.getBoundingClientRect();
    } catch (err) {
      return;
    }

    let raf = 0;
    const update = () => {
      raf = 0;

      try {
        const rect = frame.getBoundingClientRect();
        const visualViewport = parentWindow.visualViewport;
        const viewportHeight = visualViewport ? visualViewport.height : parentWindow.innerHeight;
        const viewportTop = visualViewport ? visualViewport.offsetTop : 0;
        const margin = Math.max(14, parseFloat(getComputedStyle(button).right) || 14);
        const buttonHeight = button.offsetHeight || 52;
        const documentHeight = Math.max(document.documentElement.scrollHeight, document.body.scrollHeight);
        const desiredTop = viewportTop - rect.top + viewportHeight - buttonHeight - margin;
        const maxTop = Math.max(margin, documentHeight - buttonHeight - margin);
        const nextTop = Math.min(Math.max(margin, desiredTop), maxTop);

        button.classList.add('is-embed-fixed');
        button.style.setProperty('--float-wa-top', nextTop + 'px');
      } catch (err) {
        button.classList.remove('is-embed-fixed');
        button.style.removeProperty('--float-wa-top');
      }
    };

    const schedule = () => {
      if (!raf) raf = requestAnimationFrame(update);
    };

    const listen = (target, eventName) => {
      try {
        target.addEventListener(eventName, schedule, { passive: true });
        this._observers.push({ disconnect: () => target.removeEventListener(eventName, schedule) });
      } catch (err) {}
    };

    listen(parentWindow, 'scroll');
    listen(parentWindow, 'resize');
    listen(window, 'resize');
    listen(window, 'load');
    if (parentWindow.visualViewport) {
      listen(parentWindow.visualViewport, 'resize');
      listen(parentWindow.visualViewport, 'scroll');
    }
    if (window.ResizeObserver) {
      const resizeObserver = new ResizeObserver(schedule);
      resizeObserver.observe(document.body);
      this._observers.push(resizeObserver);
    }

    schedule();
  }
}

if (!customElements.get('acopla-lp')) {
  customElements.define('acopla-lp', AcoplaLandingPage);
}
